insert into public.portfolio_advisory_renewal_assessments
 (owner_id,initiative,status,inputs,analysis,model_version,synthetic,next_review)
select u.id,e.initiative,'decision_recorded',e.inputs,e.analysis,'renewal-v1.0.0',true,e.review_date::date
from examples e cross join admin_user u
where not exists (
 select 1 from public.portfolio_advisory_renewal_assessments a
 where a.owner_id=u.id and a.initiative=e.initiative and a.synthetic=true
);
-- A synthetic executive signoff is a separate, explicitly labeled historical act.
with examples(initiative,choice,rationale) as (
 values
 ('[SYNTHETIC DEMO] Knowledge assistant versus process ownership','REPLACE','Process changes address the recurring workflow defect and have greater prospective value after transition cost.'),
('[SYNTHETIC DEMO] Field-service AI triage renewal','RENEW','The incumbent''s observed service benefit justifies the next bounded investment over the available alternative.'),
('[SYNTHETIC DEMO] Predictive quality intervention','TEST','Near-term benefits are uncertain; a bounded experiment should resolve signal quality and operating readiness.'),
('[SYNTHETIC DEMO] Autonomous meeting summarization','STOP','Both options have negative prospective monetary value; discontinue discretionary build after orderly exit.'),
('[SYNTHETIC DEMO] Mandatory customer support continuity','HOLD','The proposed replacement cannot yet satisfy mandatory service obligations and has an unresolved control blocker.')
)
insert into public.portfolio_advisory_renewal_decisions
 (assessment_id,owner_id,authorized_action,recommendation_at_signoff,rationale,
  authorized_by,next_review,supporting_revision,synthetic)
select a.id,a.owner_id,e.choice,e.choice,'SYNTHETIC DEMONSTRATION. '||e.rationale,
 'Synthetic investment committee','2027-02-15'::date,a.revision,true
from examples e join public.portfolio_advisory_renewal_assessments a
 on a.initiative=e.initiative and a.synthetic=true
where not exists (select 1 from public.portfolio_advisory_renewal_decisions d
 where d.assessment_id=a.id and d.synthetic=true);
